// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount, address other) public {
        vm.assume(actor != address(0) && actor != address(c) && other != address(c) && actor != other);
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.deal(actor, amount);

        uint256 balanceBefore = address(c).balance;
        uint256 actorBalanceBefore = c.getBalance(actor);
        uint256 otherBalanceBefore = c.getBalance(other);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 balanceAfter = address(c).balance;
        uint256 actorBalanceAfter = c.getBalance(actor);
        uint256 otherBalanceAfter = c.getBalance(other);

        assertTrue(
            (balanceAfter == balanceBefore + amount) &&
            (actorBalanceAfter == actorBalanceBefore + amount) &&
            (otherBalanceAfter == otherBalanceBefore)
        );
    }
}
